function stable(value) {
  if (Array.isArray(value)) return value.map(stable);
  if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).sort(([left], [right]) => left.localeCompare(right)).map(([key, item]) => [key, stable(item)]));
  return value;
}

function valueAt(value, tokens) {
  return tokens.reduce((current, token) => current?.[token], value);
}

function nearestValue(value, tokens) {
  for (let length = tokens.length; length >= 0; length -= 1) {
    const selected = valueAt(value, tokens.slice(0, length));
    if (selected !== undefined) {
      const encoded = JSON.stringify(stable(selected));
      return {
        path: tokens.slice(0, length),
        valueKind: Array.isArray(selected) ? 'array' : selected === null ? 'null' : typeof selected,
        valueSha256: sha256(encoded),
        value: encoded.length <= 1000 ? selected : undefined,
        topLevelKeys: encoded.length > 1000 && selected && typeof selected === 'object' ? Object.keys(selected).sort() : undefined,
      };
    }
  }
  throw new Error(`values.yaml has no ancestor for ${tokens.join('.')}`);
}

function schemaAt(schema, tokens) {
  let current = schema;
  const resolved = [];
  for (const token of tokens) {
    if (!current) break;
    if (typeof token === 'number') current = current.items;
    else current = current.properties?.[token] ?? (typeof current.additionalProperties === 'object' ? current.additionalProperties : null);
    if (!current) break;
    resolved.push(token);
  }
  if (!current) return null;
  const selected = Object.fromEntries(['type', 'description', 'default', 'enum', 'minimum', 'maximum', 'pattern', 'format', 'required']
    .filter((key) => current[key] !== undefined).map((key) => [key, current[key]]));
  return { path: resolved, contract: selected };
}

function walk(directory) {
  if (!fs.existsSync(directory)) return [];
  return fs.readdirSync(directory, { recursive: true, withFileTypes: true })
    .filter((entry) => entry.isFile())
    .map((entry) => path.join(entry.parentPath, entry.name));
}

function templateEvidence(chartDirectory, tokens) {
  const stringTokens = tokens.filter((token) => typeof token === 'string');
  const candidates = [];
  for (let length = stringTokens.length; length > 0; length -= 1) candidates.push(`.Values.${stringTokens.slice(0, length).join('.')}`);
  const result = [];
  for (const absolute of walk(path.join(chartDirectory, 'templates'))) {
    const lines = fs.readFileSync(absolute, 'utf8').split('\n');
    lines.forEach((line, index) => {
      const matchedPrefix = candidates.find((candidate) => line.includes(candidate));
      if (!matchedPrefix) return;
      const context = lines.slice(Math.max(0, index - 2), Math.min(lines.length, index + 3)).join('\n');
      result.push({
        path: path.relative(chartDirectory, absolute).replaceAll(path.sep, '/'),
        line: index + 1,
        matchedPrefix,
        context,
        contextSha256: sha256(context),
      });
    });
  }
  const mostSpecific = Math.max(0, ...result.map((item) => item.matchedPrefix.split('.').length));
  return result.filter((item) => item.matchedPrefix.split('.').length === mostSpecific)
    .sort((left, right) => `${left.path}:${left.line}`.localeCompare(`${right.path}:${right.line}`));
}

function extractChart(key, chart, archive, directory) {
  const archiveBytes = fs.readFileSync(archive);
  assert.equal(sha256(archiveBytes), chart.archiveSha256, `${key}: archive digest differs from the checked-in lock`);
  const extracted = path.join(directory, 'extracted');
  fs.mkdirSync(extracted);
  const untarred = spawnSync('tar', ['--no-same-owner', '-xzf', archive, '-C', extracted], { encoding: 'utf8' });
  if (untarred.status !== 0) throw new Error(`${key}: chart extraction failed: ${untarred.stderr}`);
  const children = fs.readdirSync(extracted).map((name) => path.join(extracted, name)).filter((candidate) => fs.statSync(candidate).isDirectory());
  assert.equal(children.length, 1, `${key}: archive does not contain one chart directory`);
  return children[0];
}

function pullChart(key, chart, directory) {
  const isOci = !chart.repository.startsWith('http');
  const reference = isOci ? `oci://${chart.repository}/${chart.chart}` : chart.chart;
  const args = ['pull', reference, '--version', chart.version, '--destination', directory];
  if (!isOci) args.push('--repo', chart.repository);
  const pulled = spawnSync('helm', args, { cwd: root, encoding: 'utf8' });
  if (pulled.status !== 0) throw new Error(`failed to pull ${key}: ${pulled.stderr || pulled.stdout}`);
  const archives = fs.readdirSync(directory).filter((name) => name.endsWith('.tgz'));
  assert.equal(archives.length, 1, `${key}: expected one chart archive`);
  const archive = path.join(directory, archives[0]);
  const archiveBytes = fs.readFileSync(archive);
  assert.equal(sha256(archiveBytes), chart.archiveSha256, `${key}: archive digest differs from the checked-in lock`);
  return archive;
}

function inventoryExternalFields() {
  const inventory = JSON.parse(fs.readFileSync(inventoryPath, 'utf8'));
  const result = [];
  for (const file of inventory.files) for (const document of file.documents) for (const field of document.fields ?? []) {
    if (field.meaning?.status !== 'external-chart-authority') continue;
    result.push({ sourcePath: file.path, fieldPath: field.path, selectedValue: field.value, externalChart: field.meaning.externalChart });
  }
  return result;
}

function deriveArtifact(archiveManifest) {
  const fields = inventoryExternalFields();
  const output = { version: 2, generatedBy: 'scripts/vendor-external-helm-authorities.mjs', lockSha256: sha256(fs.readFileSync(lockPath)), archiveManifestSha256: sha256(fs.readFileSync(archiveManifestPath)), charts: {}, templateContexts: {}, fields: {} };
  const temporaryRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'kubeclaw-external-helm-authority-'));
  try {
    for (const [key, chart] of Object.entries(lock.charts)) {
      const directory = path.join(temporaryRoot, key);
      fs.mkdirSync(directory);
      const archiveEntry = archiveManifest.charts[key];
      assert(archiveEntry, `${key}: vendored chart archive manifest entry is missing`);
      assert.equal(archiveEntry.sha256, chart.archiveSha256, `${key}: vendored archive manifest differs from chart lock`);
      const archive = path.join(root, archiveEntry.path);
      assert(fs.existsSync(archive), `${key}: vendored chart archive is missing: ${archiveEntry.path}`);
      const archiveBytes = fs.readFileSync(archive);
      assert.equal(archiveBytes.length, archiveEntry.size, `${key}: vendored archive byte count changed`);
      assert.equal(sha256(archiveBytes), archiveEntry.sha256, `${key}: vendored archive bytes changed`);
      const chartDirectory = extractChart(key, chart, archive, directory);
      const valuesBytes = fs.readFileSync(path.join(chartDirectory, 'values.yaml'));
      assert.equal(sha256(valuesBytes), chart.valuesSha256, `${key}: extracted values.yaml digest differs from the checked-in lock`);
      const schemaPath = path.join(chartDirectory, 'values.schema.json');
      const schemaBytes = fs.existsSync(schemaPath) ? fs.readFileSync(schemaPath) : null;
      if (chart.schemaSha256) {
        assert(schemaBytes, `${key}: locked schema is missing from archive`);
        assert.equal(sha256(schemaBytes), chart.schemaSha256, `${key}: extracted schema digest differs from the checked-in lock`);
      }
      const values = YAML.parse(valuesBytes.toString('utf8'));
      const schema = schemaBytes ? JSON.parse(schemaBytes) : null;
      output.charts[key] = { ...chart, extractedValuesSha256: sha256(valuesBytes), extractedSchemaSha256: schemaBytes ? sha256(schemaBytes) : null };
      for (const field of fields.filter((item) => item.externalChart.chart === chart.chart && item.externalChart.version === chart.version
        && item.externalChart.archiveSha256 === chart.archiveSha256)) {
        const tokens = yamlFieldPathTokens(field.fieldPath);
        const upstream = nearestValue(values, tokens);
        const schemaContract = schemaAt(schema, tokens);
        const templates = templateEvidence(chartDirectory, tokens);
        const templateContextIds = templates.map((template) => {
          const id = sha256(JSON.stringify(stable(template)));
          output.templateContexts[id] ??= template;
          return id;
        });
        const keyName = `${field.sourcePath}#${field.fieldPath}`;
        output.fields[keyName] = {
          chartKey: key,
          selectedValue: field.selectedValue,
          upstreamValue: upstream,
          schema: schemaContract,
          templateContextIds,
          authorityMode: templateContextIds.length ? 'extracted-template-and-values' : schemaContract ? 'extracted-schema-and-values' : 'extracted-values-nearest-ancestor',
        };
      }
    }
  } finally {
    fs.rmSync(temporaryRoot, { recursive: true, force: true });
  }
  return `${JSON.stringify(stable(output), null, 2)}\n`;
}

function readArchiveManifest() {
  assert(fs.existsSync(archiveManifestPath) && fs.existsSync(archiveManifestChecksumPath),
    'vendored external Helm archive manifest is missing; prepare the approved archive inputs first');
  const bytes = fs.readFileSync(archiveManifestPath);
  const [expected, name] = fs.readFileSync(archiveManifestChecksumPath, 'utf8').trim().split(/\s+/u);
  assert.equal(name, path.basename(archiveManifestPath), 'external Helm archive checksum names the wrong manifest');
  assert.equal(sha256(bytes), expected, 'external Helm archive manifest bytes changed');
  const manifest = JSON.parse(bytes);
  assert.equal(manifest.version, 1, 'unsupported external Helm archive manifest version');
  assert(manifest.charts && typeof manifest.charts === 'object' && !Array.isArray(manifest.charts),
    'external Helm archive manifest needs chart records');
  return manifest;
}

function refreshExtractedArtifact(manifest = readArchiveManifest()) {
  const bytes = deriveArtifact(manifest);
  fs.writeFileSync(artifactPath, bytes);
  fs.writeFileSync(checksumPath, `${sha256(bytes)}  ${path.basename(artifactPath)}\n`);
}

function refreshArtifact() {
  fs.mkdirSync(archiveDirectory, { recursive: true });
  const temporaryRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'kubeclaw-external-helm-download-'));
  // Other documentation consumers can own additional vendored chart entries.
  // Retain them; this refresh replaces only coordinates governed by this lock.
  const prior = fs.existsSync(archiveManifestPath) || fs.existsSync(archiveManifestChecksumPath)
    ? readArchiveManifest() : null;
  const manifest = { version: 1, generatedBy: 'scripts/vendor-external-helm-authorities.mjs --refresh', charts: { ...(prior?.charts ?? {}) } };
  try {
    for (const [key, chart] of Object.entries(lock.charts)) {
      const directory = path.join(temporaryRoot, key);
      fs.mkdirSync(directory);
      const downloaded = pullChart(key, chart, directory);
      const fileName = `${chart.archiveSha256}.tgz`;
      const destination = path.join(archiveDirectory, fileName);
      fs.copyFileSync(downloaded, destination);
      const bytes = fs.readFileSync(destination);
      manifest.charts[key] = {
        chart: chart.chart,
        version: chart.version,
        repository: chart.repository,
        path: path.relative(root, destination).replaceAll(path.sep, '/'),
        sha256: sha256(bytes),
        size: bytes.length,
      };
    }
  } finally {
    fs.rmSync(temporaryRoot, { recursive: true, force: true });
  }
  const manifestBytes = `${JSON.stringify(stable(manifest), null, 2)}\n`;
  fs.writeFileSync(archiveManifestPath, manifestBytes);
  fs.writeFileSync(archiveManifestChecksumPath, `${sha256(manifestBytes)}  ${path.basename(archiveManifestPath)}\n`);
  refreshExtractedArtifact(manifest);
}

function checkArtifact() {
  assert(fs.existsSync(artifactPath) && fs.existsSync(checksumPath), 'external Helm extracted authority artifact is missing; run with --refresh');
  const archiveManifest = readArchiveManifest();
  const bytes = fs.readFileSync(artifactPath);
  const artifact = JSON.parse(bytes);
  const [expected, name] = fs.readFileSync(checksumPath, 'utf8').trim().split(/\s+/u);
  assert.equal(name, path.basename(artifactPath), 'external Helm snapshot checksum names the wrong file');
  assert.equal(sha256(bytes), expected, 'external Helm extracted authority bytes changed');
  const recomputedBytes = deriveArtifact(archiveManifest);
  assert.equal(bytes.toString('utf8'), recomputedBytes, 'external Helm authority snapshot does not match a fresh offline extraction from vendored chart archives');
  assert.equal(artifact.lockSha256, sha256(fs.readFileSync(lockPath)), 'external Helm extracted authority uses a different chart lock');
  const inventoryFields = inventoryExternalFields();
  assert.equal(Object.keys(artifact.fields).length, inventoryFields.length, 'external Helm extracted field count differs from the inventory');
  for (const field of inventoryFields) {
    const key = `${field.sourcePath}#${field.fieldPath}`;
    const proof = artifact.fields[key];
    assert(proof, `${key}: extracted external Helm authority is missing`);
    assert(proof.templateContextIds.length || proof.schema || proof.upstreamValue, `${key}: extracted authority has no vendored input`);
    assert.match(proof.upstreamValue?.valueSha256 ?? '', /^[a-f0-9]{64}$/u, `${key}: extracted upstream values evidence has no content digest`);
    for (const id of proof.templateContextIds) {
      const template = artifact.templateContexts[id];
      assert(template, `${key}: extracted template context ${id} is missing`);
      assert.equal(sha256(JSON.stringify(stable(template))), id, `${key}: extracted template context identity changed`);
      assert.equal(sha256(template.context), template.contextSha256, `${key}: extracted template context changed`);
    }
  }
  for (const [key, chart] of Object.entries(lock.charts)) assert.deepEqual(artifact.charts[key], {
    ...chart,
    extractedValuesSha256: chart.valuesSha256,
    extractedSchemaSha256: chart.schemaSha256 ?? null,
  }, `${key}: extracted chart coordinate or content digest differs from the lock`);
  console.log(`external Helm authority snapshots are current (${inventoryFields.length} exact fields across ${Object.keys(lock.charts).length} charts)`);
}

export function nativePrismDeploymentSelection(documents, namespace, policy) {
  const workload = name => documents.find(document => document?.kind === 'Deployment' && document.metadata.name === `prism-${name}`);
  const worker = workload('worker'); const control = workload('control');
  if (!worker || !control) throw new Error('NATIVE_DEPLOYMENT_WORKLOADS_REQUIRED');
  const container = (workload, name) => workload?.spec.template.spec.containers.find(container => container.name === name);
  const supervisor = container(worker, 'worker');
  if (JSON.stringify(supervisor?.command) !== JSON.stringify(['node', 'skills/prism/server/worker.ts'])
    || worker.spec.template.metadata.annotations?.['kubeclaw.dev/native-worker-role'] !== 'prism') {
    throw new Error('NATIVE_DEPLOYMENT_PROTOCOL_MISMATCH');
  }
  const digest = value => value?.env?.find(item => item.name === 'PRISM_ENGINE_CONTENT_DIGEST')?.value;
  if (!/^sha256:[a-f0-9]{64}$/.test(digest(supervisor) ?? '')
    || digest(supervisor) !== digest(container(control, 'control'))
    || digest(supervisor) !== supervisor.image.split('@')[1]) throw new Error('NATIVE_DEPLOYMENT_IMAGE_MISMATCH');
  const pool = nativePoolPolicy(policy, 'prism');
  if (namespace !== policy.pools.prism.namespace || worker.spec.replicas !== 1
    || worker.spec.template.metadata.annotations?.['kubeclaw.dev/native-worker-policy'] !== pool.policyDigest) {
    throw new Error('NATIVE_DEPLOYMENT_POLICY_MISMATCH');
  }
  const terms = worker.spec.template.spec.affinity?.nodeAffinity?.requiredDuringSchedulingIgnoredDuringExecution?.nodeSelectorTerms;
  const expected = [{ matchFields: [{ key: 'metadata.name', operator: 'In', values: [policy.nodeName] }] }];
  if (JSON.stringify(terms) !== JSON.stringify(expected)) throw new Error('NATIVE_DEPLOYMENT_NODE_MISMATCH');
  return true;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const [policyFile, namespace, ...helmArguments] = process.argv.slice(2);
  if (!policyFile || !namespace || helmArguments[0] !== 'template') throw new Error('Usage: native-worker-deployment-preflight.mjs POLICY_YAML NAMESPACE template HELM_ARGUMENTS');
  const documents = loadAll(execFileSync('helm', helmArguments, { encoding: 'utf8', maxBuffer: 32 * 1024 * 1024 }));
  const policy = loadNativeNodePolicy(policyFile);
  nativePrismDeploymentSelection(documents, namespace, policy);
  preflightNativeWorkerNode(policy);
}

const families = {
  runtime: ['nova', 'prism-agent', 'buster-gateway', 'buster-runtime', 'namespace-controller', 'archviewer', 'prism-control', 'prism-studio', 'prism-worker', 'prism-ingestion'],
  ops: ['codex-ops', 'ops-mcp'],
};

export function validateReleaseReceipt(receipt, family) {
  const names = families[family];
  if (!names) throw new Error('Unknown release family');
  if (receipt.schemaVersion !== 1 || !/^[a-f0-9]{40}$/u.test(receipt.commit)
    || !Number.isSafeInteger(receipt.sourceRunId) || receipt.sourceRunId < 1
    || !Number.isSafeInteger(receipt.sourceRunAttempt) || receipt.sourceRunAttempt < 1
    || !receipt.images || JSON.stringify(Object.keys(receipt.images).sort()) !== JSON.stringify([...names].sort())) {
    throw new Error('Invalid complete release receipt or source run identity');
  }
  for (const name of names) {
    if (typeof receipt.images[name] !== 'string'
      || !new RegExp(`^ghcr\\.io/[a-z0-9_-]+/kubeclaw-${name}@sha256:[a-f0-9]{64}$`, 'u').test(receipt.images[name])) {
      throw new Error(`Invalid selected image slot: ${name}`);
    }
  }
  if (receipt.code) validateCodeReceipt(receipt.code);
  return receipt;
}

export function selectedRelease(root, family) {
  const names = families[family];
  if (!names) throw new Error('Unknown release family');
  const file = path.join(root, `releases/${family}-images.json`);
  if (!fs.existsSync(file)) throw new Error(`No selected ${family} release. Merge the Promote image release selection PR, then run node scripts/updates/materialize-release.mjs --family=${family}; no latest fallback is available.`);
  const receipt = JSON.parse(fs.readFileSync(file, 'utf8'));
  validateReleaseReceipt(receipt, family);
  execFileSync(process.execPath, [path.join(import.meta.dirname, 'materialize-release.mjs'), `--family=${family}`, '--check'], { cwd: root, stdio: ['ignore', 'pipe', 'pipe'] });
  const code = family === 'runtime' ? selectedCode(root, receipt) : undefined;
  return code ? { ...receipt, code } : receipt;
}

function containerSlots(manifest) {
  const slots = new Map();
  const visit = (value, key) => {
    if (!value || typeof value !== 'object') return;
    for (const field of ['containers', 'initContainers']) {
      for (const container of value[field] ?? []) {
        const id = `${key}/${field}/${container.name}`;
        if (slots.has(id)) throw new Error(`Duplicate image slot: ${id}`);
        slots.set(id, container);
      }
    }
    for (const [field, child] of Object.entries(value)) {
      if (!['containers', 'initContainers'].includes(field)) visit(child, key);
    }
  };
  yaml.loadAll(manifest, document => {
    if (document) visit(document, `${document.kind}/${document.metadata?.name}`);
  });
  return slots;
}

function bundleVariables(container) {
  const variables = new Map();
  for (const variable of container?.env ?? []) {
    if (!/^(?:KUBECLAW_)?CODE_BUNDLE_/u.test(variable.name)) continue;
    if (variables.has(variable.name)) throw new Error(`Duplicate reserved bundle control: ${variable.name}`);
    variables.set(variable.name, variable);
  }
  return variables;
}

function validateBundleVariableShape(actual, expected, slot) {
  for (const [name, variable] of actual) {
    // Authentication can introduce the chart's conditional Secret reference.
    if (name.endsWith('_AUTH_TOKEN')) continue;
    if (!expected.has(name)) throw new Error(`Unexpected reserved bundle control: ${slot}/${name}`);
    if (variable.valueFrom || typeof variable.value !== 'string') throw new Error(`Indirect reserved bundle control: ${slot}/${name}`);
  }
  for (const name of expected.keys()) {
    if (!name.endsWith('_AUTH_TOKEN') && !actual.has(name)) throw new Error(`Missing reserved bundle control: ${slot}/${name}`);
  }
}

function validateBundle(container, baseline, slot, receipt, requireBundle) {
  const actual = bundleVariables(container);
  const expected = bundleVariables(baseline);
  validateBundleVariableShape(actual, expected, slot);
  let consumers = 0;
  for (const name of ['CODE_BUNDLE_ENABLED', 'KUBECLAW_CODE_BUNDLE_ENABLED']) {
    if (!expected.has(name)) continue;
    const enabled = actual.get(name)?.value;
    if (!['true', 'false'].includes(enabled) || ((requireBundle || receipt.code) && enabled !== 'true')) throw new Error(`Canonical bundle consumer disabled: ${slot}/${name}`);
    const prefix = name.slice(0, -'ENABLED'.length);
    const commit = receipt.code?.commit ?? receipt.commit;
    const revision = actual.get(`${prefix}EXPECTED_COMMIT`)?.value;
    if ((enabled === 'true' || revision !== '') && revision !== commit) throw new Error(`Bundle commit differs from selected runtime: ${slot}`);
    if (actual.get(`${prefix}CONTRACT_VERSION`)?.value !== 'v2') throw new Error(`Unsupported bundle contract: ${slot}`);
    if (enabled === 'true' && receipt.code && prefix === 'CODE_BUNDLE_') {
      const url = actual.get(`${prefix}ARCHIVE_URL`)?.value;
      const bundle = Object.values(receipt.code.bundles).find(item => item.url === url);
      if (!bundle || actual.get(`${prefix}SHA256`)?.value !== bundle.sha256) throw new Error(`Unselected code bundle: ${slot}`);
      const role = container.env?.find(item => item.name === 'AGENT_NAME')?.value;
      if (!receipt.code.bundles[role] || receipt.code.bundles[role].url !== url) throw new Error(`Wrong code bundle role: ${slot}`);
    }
    consumers += 1;
  }
  return consumers;
}

export function validateRenderedRelease(baseline, rendered, receipt, requireBundle = false) {
  const expected = containerSlots(baseline);
  const actual = containerSlots(rendered);
  const refs = new Set(Object.values(receipt.images));
  for (const [slot, container] of expected) {
    if (refs.has(container.image) && actual.get(slot)?.image !== container.image) {
      throw new Error(`Selected release image slot changed or missing: ${slot}`);
    }
  }
  let bundleConsumers = 0;
  for (const [slot, container] of actual) {
    if (/\/kubeclaw-[^/]+(?:@|:)/u.test(container.image ?? '') && !refs.has(container.image)) {
      throw new Error(`Unselected first-party image: ${slot}`);
    }
    bundleConsumers += validateBundle(container, expected.get(slot), slot, receipt, requireBundle);
  }
  if (requireBundle && bundleConsumers === 0) throw new Error('Selected code bundle is missing from rendered workload');
}

function withDeploymentContext(args, role, run) {
  const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'release-registry-context-'));
  const context = [];
  try {
    for (let index = 0; index < args.length - 1; index += 1) {
      if (!['-f', '--values'].includes(args[index])) continue;
      const values = yaml.load(fs.readFileSync(args[++index], 'utf8'));
      const registry = values?.runtimeInfrastructure?.registry;
      const native = role === 'prism' ? values?.worker?.native : undefined;
      const binding = native && Object.fromEntries(['nodeName', 'namespace', 'policyDigest']
        .filter(key => native[key] !== undefined).map(key => [key, native[key]]));
      if (registry === undefined && (!binding || !Object.keys(binding).length)) continue;
      const file = path.join(temporary, `${index}.yaml`);
      fs.writeFileSync(file, yaml.dump({ ...(registry === undefined ? {} : { runtimeInfrastructure: { registry } }),
        ...(binding && Object.keys(binding).length ? { worker: { native: binding } } : {}) }), { mode: 0o600 });
      context.push('-f', file);
    }
    return run(context);
  } finally { fs.rmSync(temporary, { recursive: true, force: true }); }
}

function validateOverlays(args, root, role, baseline, render, receipt) {
  // Validate each explicit values overlay before a later override can conceal
  // a conflicting image or bundle choice. Helm performs the actual merge.
  let selectedSeen = false;
  for (let index = 0; index < args.length - 1; index += 1) {
    if (!['-f', '--values'].includes(args[index])) continue;
    const file = args[index + 1];
    const values = yaml.load(fs.readFileSync(file, 'utf8'));
    const commit = values?.codeBundle?.expectedCommit;
    if (commit && commit !== (receipt.code?.commit ?? receipt.commit)) throw new Error('Overlay bundle commit differs from selected runtime');
    if (selectedSeen) validateRenderedRelease(baseline, render(args.slice(0, index + 2)), receipt);
    selectedSeen ||= path.resolve(file) === path.join(root, `releases/values/${role}.yaml`);
    index += 1;
  }
  if (!selectedSeen) throw new Error('Selected release values are required');
}

if (process.argv[1] === import.meta.filename) {
  const [command, root, family, role, release, namespace, ...options] = process.argv.slice(2);
  const receipt = selectedRelease(root, family);
  if (command === 'verify') process.stdout.write(`${receipt.code?.commit ?? receipt.commit}\n`);
  else if (command === 'render') {
    const separator = options.indexOf('--');
    if (separator < 0) throw new Error('Helm values argument separator required');
    const control = options.slice(0, separator);
    const args = options.slice(separator + 1);
    if (!(family === 'ops' ? ['ops'] : ['nova', 'buster', 'prism-agent', 'prism']).includes(role)) throw new Error('Invalid release role');
    const chart = path.join(root, 'charts', role === 'ops' ? 'ops-pod' : role === 'prism' ? 'prism' : 'kubeclaw');
    const common = ['template', release, chart, '--namespace', namespace];
    const discovery = control.find(arg => arg.startsWith('--discovery='))?.slice('--discovery='.length);
    const baselineArgs = discovery ? ['-f', discovery] : [];
    baselineArgs.push('-f', path.join(root, `releases/values/${role}.yaml`));
    const render = values => execFileSync('helm', [...common, ...values], { encoding: 'utf8', maxBuffer: 32 * 1024 * 1024 });
    withDeploymentContext(args, role, context => {
      const baseline = render([...baselineArgs, ...context]);
      validateOverlays(args, root, role, baseline, values => render([...context, ...values]), receipt);
      const rendered = render(args);
      validateRenderedRelease(baseline, rendered, receipt, control.includes('--bundle'));
      process.stdout.write(rendered);
    });
  } else throw new Error('Unknown deployment release command');
}

function render(name, chart, values = [], stringSets = [], typedSets = []) {
  const args = ['template', name, chart];
  for (const value of values) args.push('-f', value);
  for (const setting of stringSets) args.push('--set-string', setting);
  for (const setting of typedSets) args.push('--set', setting);
  return execFileSync('helm', args, {
    cwd: root,
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
  });
}

function documents(source) {
  return source.split(/(?=^---\s*$)/gmu).flatMap((chunk) => {
    const document = YAML.parseDocument(chunk);
    if (document.errors.length > 0 || !document.toJSON()) return [];
    return [document.toJSON()];
  });
}

function walk(directory) {
  return fs.readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
    const target = path.join(directory, entry.name);
    return entry.isDirectory() ? walk(target) : entry.isFile() ? [target] : [];
  });
}

const renders = [
  ['nova-core', render('agent-nova', 'charts/kubeclaw', ['my-values/nova-values.yaml'], [], [
    'archviewer.enabled=false',
  ])],
  ['buster', render('agent-buster', 'charts/kubeclaw', ['my-values/buster-values.yaml'], [
    'runtimeInfrastructure.registry.endpoint=http://registry-local.kubeclaw.svc.cluster.local:5001',
    'runtimeInfrastructure.registry.transport=http-lab',
  ])],
  ['prism-agent', render('agent-prism', 'charts/kubeclaw', ['my-values/prism-agent-values.yaml'])],
  ['prism', render('prism', 'charts/prism', ['my-values/prism-values.yaml'], [
    'worker.native.namespace=kubeclaw',
    'worker.native.nodeName=cni-portability-node',
    `worker.native.policyDigest=${'a'.repeat(64)}`,
  ])],
];

for (const [profile, source] of renders) {
  const resources = documents(source);
  const ciliumResources = resources.filter((resource) =>
    forbiddenKinds.has(resource.kind) || String(resource.apiVersion ?? '').startsWith('cilium.io/'));
  assert.deepEqual(ciliumResources, [],
    `${profile} core profile renders Cilium-specific resources`);
  renderSummary.push({
    profile,
    resources: resources.length,
    networkPolicies: resources.filter((resource) => resource.kind === 'NetworkPolicy').length,
  });
}

assert.deepEqual(maintainedNovaCiliumResources.map((resource) =>
  `${resource.kind}/${resource.metadata?.name}`).sort(), [
  'CiliumNetworkPolicy/agent-nova-archviewer',
], 'the maintained Nova profile gained an unclassified Cilium dependency');

const runtimeRoots = [
  'skills/nova/core',
  'skills/worker/core',
  'skills/buster/engine',
  'skills/prism/server',
];

const sourceFiles = runtimeRoots.flatMap((directory) => walk(path.join(root, directory)))
  .filter((file) => /\.(?:ts|mts|mjs|js|json)$/u.test(file)
    && !/(?:^|\/)(?:tests?|fixtures)\//u.test(file)
    && !/\.(?:test|spec)\.[^.]+$/u.test(file));

for (const file of sourceFiles) {
  const source = fs.readFileSync(file, 'utf8');
  if (/cilium\.io|CiliumNetworkPolicy|CiliumClusterwideNetworkPolicy/u.test(source)) {
    ciliumBindings.push(path.relative(root, file).split(path.sep).join('/'));
  }
}

process.stdout.write(`${JSON.stringify({
  ok: true,
  proof: 'render-and-source-portability',
  liveFlannelDeploymentProved: false,
  profiles: renderSummary,
  currentProfileCiliumBoundary: {
    profile: 'nova',
    optionalComponent: 'archviewer',
    resources: maintainedNovaCiliumResources.map((resource) =>
      `${resource.kind}/${resource.metadata?.name}`),
  },
  runtimeSourceFilesChecked: sourceFiles.length,
})}\n`);

