export function renderInfrastructureChart(name, release, namespace, archive, values, helm, upgrade = false) {
  const output = execFileSync(helm, ['template', release, archive, '--namespace', namespace, '-f', values,
    '--post-renderer', path.join(root, 'scripts/infrastructure-image-renderer.mjs'), '--post-renderer-args', name,
    ...(upgrade ? ['--is-upgrade'] : []), ...(name === 'postgresql' ? ['--set-string', `auth.password=${renderMarker}`] : [])],
  { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, stdio: ['ignore', 'pipe', 'pipe'] });
  const documents = loadAll(output).filter(Boolean);
  // Upstream invokes its password-generation helper even with existingSecret.
  // This offline-only input must have NO effect on any emitted resource. It is
  // never supplied to helm upgrade, never stored and never used to authenticate.
  if (name === 'postgresql' && (documents.some(document => document.kind === 'Secret')
    || output.includes(renderMarker) || output.includes(Buffer.from(renderMarker).toString('base64')))) {
    throw new Error('INFRASTRUCTURE_POSTGRESQL_EXTERNAL_SECRET_REQUIRED');
  }
  bindInfrastructureImages(name, documents);
  return output;
}

export function prepareInfrastructureRelease(name, release, namespace, values, helm = 'helm') {
  for (const [value, maximum] of [[release, 53], [namespace, 63]]) {
    if (!/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/.test(value) || value.length > maximum) throw new Error('INFRASTRUCTURE_RELEASE_IDENTITY_INVALID');
  }
  const archive = stageInfrastructureChart(name);
  for (const upgrade of [false, true]) {
    // Helm post-renderers do not receive hooks. Also inspect the complete result
    // here, so a mutable test/init image cannot escape the deployment preflight.
    renderInfrastructureChart(name, release, namespace, archive, values, helm, upgrade);
  }
  return archive;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.length !== 6) throw new Error('Usage: infrastructure-release.mjs PROFILE RELEASE NAMESPACE VALUES');
  console.log(prepareInfrastructureRelease(...process.argv.slice(2)));
}

export function infrastructureChart(name) {
  const manifest = JSON.parse(fs.readFileSync(path.join(root, 'versions.json'), 'utf8'));
  const lock = manifest.infrastructureCharts?.[name];
  return validateInfrastructureChartLock(lock);
}

export function verifyInfrastructureChart(name, file) {
  const lock = infrastructureChart(name);
  const stat = fs.lstatSync(file);
  if (!stat.isFile() || stat.size < 1 || stat.size > maximumBytes) throw new Error('INFRASTRUCTURE_CHART_FILE_INVALID');
  const digest = createHash('sha256').update(fs.readFileSync(file)).digest('hex');
  if (digest !== lock.sha256) throw new Error('INFRASTRUCTURE_CHART_DIGEST_MISMATCH');
  // A version tag alone is insufficient: the checked archive also includes its
  // exact packaged dependencies. Never run helm dependency update at deployment.
  const metadata = load(execFileSync('tar', ['-xOf', file, `${lock.name}/Chart.yaml`], { encoding: 'utf8', maxBuffer: maximumBytes }));
  if (metadata.name !== lock.name || metadata.version !== lock.version) throw new Error('INFRASTRUCTURE_CHART_IDENTITY_MISMATCH');
  if (lock.appVersion !== undefined && metadata.appVersion !== lock.appVersion) throw new Error('INFRASTRUCTURE_CHART_APP_VERSION_MISMATCH');
  return { name: lock.name, version: lock.version, appVersion: metadata.appVersion, sha256: digest };
}

export function stageInfrastructureChart(name) {
  const lock = infrastructureChart(name);
  const cache = path.join(os.tmpdir(), `kubeclaw-infrastructure-charts-${process.getuid()}`);
  fs.mkdirSync(cache, { recursive: true, mode: 0o700 });
  const stat = fs.lstatSync(cache);
  if (!stat.isDirectory() || stat.uid !== process.getuid() || (stat.mode & 0o077) !== 0) {
    throw new Error('INFRASTRUCTURE_CHART_CACHE_NOT_PRIVATE');
  }
  const file = path.join(cache, `${lock.name}-${lock.version}-${lock.sha256}.tgz`);
  if (!fs.existsSync(file)) {
    const temporary = fs.mkdtempSync(path.join(cache, 'download-'));
    try {
      const download = path.join(temporary, 'chart.tgz');
      if (lock.url.startsWith('oci:')) downloadInfrastructureOciChart(lock.url, download);
      else execFileSync('curl', ['--fail', '--silent', '--show-error', '--location', '--proto', '=https',
        '--proto-redir', '=https', '--retry', '4', '--retry-max-time', '120', '--connect-timeout', '15', '--max-time', '60', '--max-filesize', String(maximumBytes),
        '--output', download, lock.url], { stdio: ['ignore', 'ignore', 'inherit'] });
      verifyInfrastructureChart(name, download);
      fs.renameSync(download, file);
    } finally { fs.rmSync(temporary, { recursive: true, force: true }); }
  }
  verifyInfrastructureChart(name, file);
  return file;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const [name, file] = process.argv.slice(2);
  if (!name || process.argv.length > 4) throw new Error('Usage: infrastructure-chart.mjs NAME [ARCHIVE_TO_VERIFY]');
  console.log(file ? JSON.stringify(verifyInfrastructureChart(name, file)) : stageInfrastructureChart(name));
}

export function bindInfrastructureImages(name, documents) {
  if (!['tailscale', 'redis', 'postgresql'].includes(name)) throw new Error('INFRASTRUCTURE_IMAGE_PROFILE_INVALID');
  const images = JSON.parse(fs.readFileSync(path.join(root, 'versions.json'), 'utf8')).infrastructure;
  const result = structuredClone(documents);
  for (const document of result) {
    const pod = podSpec(document);
    if (!pod) continue;
    for (const container of [...(pod.initContainers ?? []), ...(pod.containers ?? [])]) {
      if (!/^\S+@sha256:[a-f0-9]{64}$/.test(container.image)) throw new Error('INFRASTRUCTURE_IMAGE_NOT_PINNED');
      verifyReservedImage(name, container, images);
    }
  }
  return result;
}

function podSpec(document) {
  if (document.kind === 'Pod') return document.spec;
  if (document.kind === 'CronJob') return document.spec?.jobTemplate?.spec?.template?.spec;
  if (['Deployment', 'StatefulSet', 'DaemonSet', 'Job', 'ReplicaSet'].includes(document.kind)) return document.spec?.template?.spec;
  return null;
}

function verifyReservedImage(name, container, images) {
  const variables = container.env ?? [];
  if (new Set(variables.map(variable => variable.name)).size !== variables.length) throw new Error('INFRASTRUCTURE_DUPLICATE_ENVIRONMENT');
  if (['redis', 'postgresql'].includes(name) && container.image !== images[name].replace(/:[^:@]+@/, '@')) {
    throw new Error('INFRASTRUCTURE_DATABASE_IMAGE_OVERRIDE');
  }
  if (name === 'tailscale' && container.name === 'operator') {
    const proxy = variables.find(variable => variable.name === 'PROXY_IMAGE');
    if (!proxy) throw new Error('INFRASTRUCTURE_PROXY_IMAGE_REQUIRED');
    const digestOnly = reference => reference.replace(/:[^:@]+@/, '@');
    if (container.image !== digestOnly(images.tailscaleOperator) || proxy.value !== digestOnly(images.tailscaleProxy)) {
      throw new Error('INFRASTRUCTURE_TAILSCALE_IMAGE_OVERRIDE');
    }
  }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.length !== 3) throw new Error('Usage: infrastructure-image-renderer.mjs PROFILE');
  let bytes = 0;
  const chunks = [];
  for await (const chunk of process.stdin) {
    bytes += chunk.length;
    if (bytes > 64 * 1024 * 1024) throw new Error('INFRASTRUCTURE_RENDER_LIMIT');
    chunks.push(chunk);
  }
  const documents = loadAll(Buffer.concat(chunks).toString('utf8')).filter(Boolean);
  process.stdout.write(bindInfrastructureImages(process.argv[2], documents)
    .map(document => dump(document, { noRefs: true, lineWidth: -1 })).join('---\n'));
}

